<script setup lang="ts">
import { ref,onMounted,onBeforeUnmount,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { request,api } from '@/api/client'
import { researchApi } from '@/api/research'
import { authStore } from '@/stores/auth'
interface Document {id:string;title:string;format:string;createdAt:string}
interface Passage {id:string;documentId:string;positionNumber:number;locator:string;body:string}
const docs=ref<Document[]>([]),parts=ref<Passage[]>([]),selected=ref(''),index=ref(0),busy=ref(false),error=ref(''),route=useRoute(),router=useRouter(),controller=new AbortController()
const current=computed(()=>parts.value[index.value]);let epoch=0
async function load(){docs.value=await request<Document[]>('/research/documents',{signal:controller.signal})}
async function open(id:string,passage?:string){const version=++epoch;selected.value=id;parts.value=[];index.value=0;error.value='';try{const result=await request<Passage[]>('/research/documents/'+id,{signal:controller.signal});if(version===epoch&&!controller.signal.aborted){parts.value=result;index.value=Math.max(0,result.findIndex(p=>p.id===passage))}}catch(e){if(version===epoch&&!controller.signal.aborted)error.value=(e as Error).message}}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;busy.value=true;error.value='';try{const form=new FormData();form.set('file',file);const doc=await request<Document>('/research/documents',{method:'POST',body:form,signal:controller.signal});await load();await open(doc.id)}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}finally{busy.value=false}}
async function capture(){if(!current.value||busy.value)return;busy.value=true;try{const n=await researchApi.capture('DOCUMENT',current.value.id);if(!controller.signal.aborted)void router.push('/app/notes/'+n.id+'/edit')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(){if(!selected.value||!confirm('移除这份文档的搜索内容？已有笔记副本会保留。'))return;busy.value=true;try{await request('/research/documents/'+selected.value,{method:'DELETE'});epoch++;selected.value='';parts.value=[];await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function download(){try{await api.download('/research/documents/'+selected.value+'/original',docs.value.find(d=>d.id===selected.value)?.title||'document')}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{await load();if(route.query.passage){const p=await request<Passage>('/research/documents/passages/'+encodeURIComponent(String(route.query.passage)),{signal:controller.signal});await open(p.documentId,p.id)}else if(route.query.document)await open(String(route.query.document))}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}})
onBeforeUnmount(()=>{epoch++;controller.abort()})
</script>
<template><div><header class="research-section-title"><div><h2>把资料读进知识库</h2><p class="research-hint">导入 PDF 或 Word .docx，即可搜索正文、引用原文和制作笔记。最多 10 MB、300 页。</p></div><label v-if="authStore.has('note:write')" class="button button--dark">{{busy?'正在处理…':'导入文档'}}<input type="file" accept=".pdf,.docx" :disabled="busy" @change="upload" class="document-file-input" /></label></header><p v-if="error" role="alert" class="form-error">{{error}}</p><div class="document-reader"><aside><p v-if="!docs.length" class="research-hint">导入后的文档会显示在这里。</p><button v-for="d in docs" :key="d.id" :class="{active:selected===d.id}" :disabled="busy" @click="open(d.id)"><small>{{d.format}}</small>{{d.title}}</button></aside><section v-if="current"><header class="research-section-title"><h3>{{current.locator}}</h3><div class="research-actions"><button class="button button--ghost" @click="download">下载原文</button><button v-if="authStore.has('note:write')" class="button button--ghost" :disabled="busy" @click="capture">本段存为笔记</button></div></header><p class="document-text">{{current.body}}</p><nav class="research-pagination"><button class="button" :disabled="index===0" @click="index--">上一段</button><select v-model.number="index" aria-label="跳转到原文位置" class="field-input"><option v-for="(p,i) in parts" :key="p.id" :value="i">{{p.locator}}</option></select><button class="button" :disabled="index===parts.length-1" @click="index++">下一段</button></nav><div class="research-actions"><RouterLink :to="{path:'/app/research',query:{tab:'search',type:'DOCUMENT',source:current.id}}">引用这一段提问 →</RouterLink><button v-if="authStore.has('note:write')" class="table-action" :disabled="busy" @click="remove">移除文档</button></div><p class="research-hint">PDF 按原页码定位；Word 按段落定位。扫描件需要先 OCR，复杂排版的提取顺序请对照原文件核实。</p></section><section v-else class="research-empty">选择文档，开始阅读。</section></div></div></template>
<style scoped>.document-reader{display:grid;grid-template-columns:240px minmax(0,1fr);gap:36px;margin-top:24px}.document-reader aside{border-right:1px solid var(--line);padding-right:20px}.document-reader aside button{display:block;width:100%;text-align:left;padding:14px;background:transparent;border:0;border-left:2px solid transparent;color:var(--ink);font:inherit;cursor:pointer;overflow-wrap:anywhere}.document-reader aside small{display:block;color:var(--muted);margin-bottom:6px}.document-reader aside button.active{border-color:var(--green);background:var(--surface-soft)}.document-text{white-space:pre-wrap;line-height:2;font-size:16px;overflow-wrap:anywhere;min-height:260px}.document-file-input{position:absolute;width:1px;height:1px;opacity:0}.research-pagination select{max-width:250px}.research-actions{flex-wrap:wrap}@media(max-width:760px){.document-reader{grid-template-columns:1fr}}</style>
